class LmdbStoreConnectionLifecycleTest {

	private static final ValueFactory VALUE_FACTORY = SimpleValueFactory.getInstance();

	@AfterEach
	void clearPrefixRunProperty() {
		System.clearProperty(LmdbPrefixRunPlan.ENABLED_PROPERTY);
	}

	@Test
	void preparesDistinctCountShapeBeforeOpeningSnapshotBranch() {
		System.setProperty(LmdbPrefixRunPlan.ENABLED_PROPERTY, "true");
		LmdbSailStore backingStore = mock(LmdbSailStore.class);
		SnapshotSailStore snapshotStore = mock(SnapshotSailStore.class);
		LmdbStore sail = testSail(backingStore, snapshotStore);
		when(backingStore.mayHaveInferred()).thenReturn(false);
		when(backingStore.preparePrefixRunPlan(any(int[].class), anyBoolean(), anyBoolean(), anyBoolean(),
				anyBoolean()))
						.thenThrow(new IllegalStateException("prefix plan preparation failed"));

		try (LmdbStoreConnection connection = new LmdbStoreConnection(sail)) {
			assertThrows(IllegalStateException.class,
					() -> connection.evaluateInternal(countDistinctQuery(), null, EmptyBindingSet.getInstance(),
							false));
		}

		verify(snapshotStore, never()).getExplicitSailSourceForSnapshot();
	}

	@Test
	void closesSnapshotResourcesWhenInterlockConstructionFails() {
		System.setProperty(LmdbPrefixRunPlan.ENABLED_PROPERTY, "true");
		LmdbSailStore backingStore = mock(LmdbSailStore.class);
		SnapshotSailStore snapshotStore = mock(SnapshotSailStore.class);
		SailSource branch = mock(SailSource.class);
		SailDataset dataset = mock(SailDataset.class);
		LmdbStore sail = testSail(backingStore, snapshotStore);
		when(backingStore.mayHaveInferred()).thenReturn(false);
		when(backingStore.preparePrefixRunPlan(any(int[].class), anyBoolean(), anyBoolean(), anyBoolean(),
				anyBoolean()))
						.thenReturn(
								new LmdbPrefixRunPlan(mock(TripleIndex.class), new int[] { TripleIndex.PRED_IDX }, 1));
		when(snapshotStore.getExplicitSailSourceForSnapshot()).thenReturn(branch);
		when(branch.dataset(IsolationLevels.SNAPSHOT_READ)).thenReturn(dataset);

		try (LmdbStoreConnection connection = new FailingInterlockConnection(sail)) {
			assertThrows(IllegalStateException.class,
					() -> connection.evaluateInternal(countDistinctQuery(), null, EmptyBindingSet.getInstance(),
							false));
		}

		verify(dataset).close();
		verify(branch).close();
	}

	private static LmdbStore testSail(LmdbSailStore backingStore, SnapshotSailStore snapshotStore) {
		LmdbStore sail = mock(LmdbStore.class);
		when(sail.getSailStore()).thenReturn(snapshotStore);
		when(sail.getBackingStore()).thenReturn(backingStore);
		when(sail.getValueFactory()).thenReturn(VALUE_FACTORY);
		when(sail.getDefaultIsolationLevel()).thenReturn(IsolationLevels.SNAPSHOT_READ);
		when(sail.getConnectionEvaluationStrategyFactory()).thenReturn(new DefaultEvaluationStrategyFactory());
		return sail;
	}

	private static TupleExpr countDistinctQuery() {
		StatementPattern pattern = new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o"));
		Group group = new Group(pattern);
		group.addGroupElement(new GroupElem("count", new Count(Var.of("p"), true)));
		return new Projection(group, new ProjectionElemList(new ProjectionElem("count")));
	}

	private static final class FailingInterlockConnection extends LmdbStoreConnection {

		private FailingInterlockConnection(LmdbStore sail) {
			super(sail);
		}

		@Override
		protected <T> CloseableIteration<T> interlock(CloseableIteration<T> iter, SailClosable... closes) {
			throw new IllegalStateException("interlock construction failed");
		}
	}
}
